<script setup lang="ts">
import { onMounted,ref } from 'vue'
import { useUserInfoStore } from '@/stores/userInfo'
import { money,catalogError,type Page } from '@/api/catalog'
import { orderStatus,fulfillmentStatus,orderTime } from '@/api/orders'
import { staffOrders,staffOrder,fulfillmentEvents,changeFulfillment,type OrderSummary,type StaffOrder,type FulfillmentAudit,type FulfillmentChange } from '@/api/fulfillment'
import { refundDetail,refundOrder,type RefundDetail } from '@/api/refunds'
import { staffReturn,changeReturn,returnStatus,dispositionName,type ReturnDetail } from '@/api/returns'
const returned=ref<ReturnDetail>(),disposition=ref('')
const financial=ref<RefundDetail>()
type Action=FulfillmentAudit['action']|'ORDER_REFUND'|'REVIEW_REFUND'|'RETURN_RECEIVE'|'RETURN_REJECT'|'RETURN_REFUND'
const user=useUserInfoStore(),result=ref<Page<OrderSummary>>(),selected=ref<StaffOrder>(),events=ref<FulfillmentAudit[]>([]),page=ref(1),status=ref(''),progress=ref(''),busy=ref(false),error=ref(''),notice=ref(''),note=ref(''),needsReload=ref(false)
const pending=ref<{id:string;action:Action;payment?:string;body:FulfillmentChange&{disposition?:string}}>()
const has=(code:string)=>user.permissions.some(p=>p.code===code)
async function list(next=page.value){result.value=await staffOrders(next,status.value,progress.value);page.value=next}
async function readDetail(id:string){const [detail,history,refund,ret]=await Promise.all([staffOrder(id),has('orders.audit')?fulfillmentEvents(id):Promise.resolve([]),has('orders.refunds.read')?refundDetail(id):Promise.resolve(undefined),has('orders.returns.read')?staffReturn(id):Promise.resolve(undefined)]);selected.value=detail;events.value=history;financial.value=refund;returned.value=ret;needsReload.value=false}
async function load(next=page.value){if(busy.value)return;busy.value=true;error.value='';try{await list(next);if(selected.value)await readDetail(selected.value.order.id)}catch(e){error.value=catalogError(e)}finally{busy.value=false}}
async function open(id:string){if(busy.value||pending.value||!has('orders.read.detail'))return;busy.value=true;error.value='';notice.value='';try{await readDetail(id);note.value='';disposition.value=''}catch(e){error.value=catalogError(e)}finally{busy.value=false}}
async function submit(action?:Action,payment?:string){
 if(busy.value||needsReload.value||!selected.value)return
 if(!pending.value){if(!action||!note.value.trim()||(action==='RETURN_RECEIVE'&&!disposition.value))return;if(!window.confirm(action==='SHIP'?'記錄模擬出貨？不會建立物流託運或再次扣庫存。':action==='DELIVER'?'記錄模擬送達？這不是物流公司的送達回報。':action==='RETURN_RECEIVE'?'記錄模擬收貨驗收與庫存處置？此步不回補庫存或退款。':action==='RETURN_REJECT'?'拒絕這筆演練退貨申請？此步不退款或回補。':action==='RETURN_REFUND'?'依已保存驗收結果執行全額模擬退貨退款？不會實際轉帳。':action==='ORDER_REFUND'?'記錄全額模擬退款並回補商品庫存？不會實際轉帳。':'記錄此異常付款的全額模擬退款？不會回補庫存或實際轉帳。'))return;pending.value={id:selected.value.order.id,action,payment,body:{requestId:crypto.randomUUID(),expectedOrderVersion:selected.value.order.version,note:note.value.trim(),...(action==='RETURN_RECEIVE'?{disposition:disposition.value}:{})}}}
 busy.value=true;error.value='';notice.value='';let acknowledged=false
 try{const operation=pending.value;let replayed=false;if(operation.action==='SHIP'||operation.action==='DELIVER'){const r=await changeFulfillment(operation.id,operation.action,operation.body);selected.value=r.current;replayed=r.replayed}else if(operation.action==='RETURN_RECEIVE'||operation.action==='RETURN_REJECT'){const r=await changeReturn(operation.id,operation.action,operation.body);selected.value={...selected.value,order:r.order,canShip:false,canDeliver:false};returned.value=r.current;replayed=r.replayed}else{const r=await refundOrder(operation.id,operation.body,operation.payment,operation.action==='RETURN_REFUND');selected.value={...selected.value,order:r.order,canShip:false,canDeliver:false};financial.value=r.current;if(returned.value)returned.value={...returned.value,canReceive:false,canReject:false,canRefund:false};replayed=r.replayed}pending.value=undefined;note.value='';acknowledged=true;notice.value=replayed?'已確認前次操作，沒有重複更新或新增紀錄。':'模擬操作已保存，沒有實際轉帳或建立物流託運。';await Promise.all([list(),readDetail(operation.id)])}
 catch(e:any){if(acknowledged){needsReload.value=true;error.value='操作已確認，重新讀取資料失敗，請重新核對。'}else if([400,401,403,404,409].includes(e.response?.status)){pending.value=undefined;needsReload.value=true;error.value=catalogError(e)}else{error.value='操作回應未確認，請保留此頁並重試同一操作；不要建立新的操作。'}}finally{busy.value=false}
}
onMounted(()=>load())
</script>
<template><div class="staff-orders"><h1>訂單管理</h1><p>查看訂單與收件快照，記錄模擬出貨及送達。付款與物流皆為演練，不會實際收款或建立物流託運。</p>
<p v-if="error" class="alert alert-danger" role="alert">{{ error }}</p><p v-if="notice" class="alert alert-success" role="status">{{ notice }}</p>
<div class="filters"><div class="filter-field"><label for="order-payment-filter">付款狀態</label><select id="order-payment-filter" v-model="status" class="form-select" :disabled="busy||!!pending"><option value="">全部</option><option value="PENDING_PAYMENT">待付款</option><option value="PAID">已付款（模擬）</option><option value="REFUNDED">已退款（模擬）</option><option value="CANCELLED">已取消</option><option value="EXPIRED">已逾時</option></select></div>
<div class="filter-field"><label for="order-fulfillment-filter">配送進度</label><select id="order-fulfillment-filter" v-model="progress" class="form-select" :disabled="busy||!!pending"><option value="">全部</option><option value="UNFULFILLED">尚未出貨</option><option value="SHIPPED">已模擬出貨</option><option value="DELIVERED">已模擬送達</option></select></div><button class="btn btn-primary" :disabled="busy||!!pending" @click="load(1)">套用篩選</button><button class="btn btn-outline-primary" :disabled="busy" @click="load()">重新核對訂單</button></div>
<div class="workspace"><section class="card"><div class="card-body"><h2>訂單列表</h2><p v-if="!result" role="status">載入中…</p><p v-else-if="!result.items.length" data-testid="staff-orders-empty">沒有符合條件的訂單。</p><button v-for="order in result?.items" :key="order.id" class="order-row" :data-testid="'staff-order-'+order.id" :disabled="busy||!!pending||!has('orders.read.detail')" @click="open(order.id)"><strong>{{ orderStatus(order.status) }} · {{ money(order.totalTwd) }}</strong><span>{{ fulfillmentStatus(order.fulfillmentStatus) }}</span><small>{{ order.id }}</small><small>{{ orderTime(order.createdAt) }}（台北時間）</small></button>
<nav v-if="result&&result.total>result.pageSize" aria-label="員工訂單分頁"><button class="btn btn-outline-primary" :disabled="busy||!!pending||page===1" @click="load(page-1)">上一頁</button><span>第 {{ page }} 頁</span><button class="btn btn-outline-primary" :disabled="busy||!!pending||page*result.pageSize>=result.total" @click="load(page+1)">下一頁</button></nav></div></section>
<section class="card"><div class="card-body"><h2>訂單詳情</h2><p v-if="!selected">選擇一筆訂單查看。</p><article v-else :data-testid="'staff-detail-'+selected.order.id"><p>訂單編號 {{ selected.order.id }} · 版本 {{ selected.order.version }}</p><h3>{{ orderStatus(selected.order.status) }}</h3><p>總額 {{ money(selected.order.totalTwd) }}（配送費 {{ money(selected.order.shippingTwd) }}）</p><ul><li v-for="line in selected.order.items" :key="line.skuId">{{ line.title }} · {{ line.label }} × {{ line.quantity }} · {{ money(line.lineTotalTwd) }}</li></ul><h3>收件快照</h3><p>{{ selected.order.shipping.recipientName }} · {{ selected.order.shipping.phone }}<br>{{ selected.order.shipping.postalCode }} {{ selected.order.shipping.city }}{{ selected.order.shipping.district }}{{ selected.order.shipping.street }}</p>
<h3>配送進度</h3><p data-testid="staff-fulfillment-status">{{ fulfillmentStatus(selected.order.fulfillment.status) }}</p><p v-if="selected.order.fulfillment.trackingId">模擬貨件編號 {{ selected.order.fulfillment.trackingId }}</p><p v-if="selected.order.fulfillment.shippedAt">模擬出貨時間 {{ orderTime(selected.order.fulfillment.shippedAt) }}</p><p v-if="selected.order.fulfillment.deliveredAt">模擬送達時間 {{ orderTime(selected.order.fulfillment.deliveredAt) }}</p>
<p v-if="!selected.mockEnabled">此環境未啟用模擬配送。</p><p v-else-if="!has('orders.ship.mock')&&!has('orders.deliver.mock')">目前帳號可查看訂單，沒有配送操作權限。</p><p v-else-if="!selected.canShip&&!selected.canDeliver&&!pending">目前訂單狀態不提供新的配送操作；付款異常需先核對。</p>
<div v-if="(returned?.canReceive&&has('orders.return.receive.mock'))||(returned?.canReject&&has('orders.return.reject.mock'))||(returned?.canRefund&&has('orders.return.refund.mock'))||pending||(financial?.mockEnabled&&((financial.canRefund&&has('orders.refund.mock'))||(financial.reviews.some(r=>!r.resolved)&&has('orders.review.mock'))))||(selected.canShip&&has('orders.ship.mock'))||(selected.canDeliver&&has('orders.deliver.mock'))"><label for="fulfillment-note">操作說明（僅員工稽核可見）</label><textarea id="fulfillment-note" v-model="note" class="form-control" maxlength="500" rows="2" :disabled="busy||!!pending||needsReload" /><div v-if="returned?.canReceive&&has('orders.return.receive.mock')"><label for="return-disposition">整筆驗收庫存處置</label><select id="return-disposition" v-model="disposition" class="form-select" :disabled="busy||!!pending||needsReload"><option value="">請依驗收結果選擇</option><option value="RESTOCK">可重新入庫（退款時回補）</option><option value="NO_RESTOCK">不回補庫存</option></select></div><button v-if="pending" class="btn btn-primary mt-3" :disabled="busy||needsReload" @click="submit()">重試同一操作</button><template v-else><button v-if="selected.canShip&&has('orders.ship.mock')" class="btn btn-primary mt-3" :disabled="busy||needsReload||!note.trim()" @click="submit('SHIP')">記錄模擬出貨</button><button v-if="selected.canDeliver&&has('orders.deliver.mock')" class="btn btn-primary mt-3" :disabled="busy||needsReload||!note.trim()" @click="submit('DELIVER')">記錄模擬送達</button><button v-if="financial?.canRefund&&has('orders.refund.mock')" class="btn btn-danger mt-3" :disabled="busy||needsReload||!note.trim()" @click="submit('ORDER_REFUND')">記錄全額模擬退款</button><template v-if="financial?.mockEnabled&&has('orders.review.mock')"><button v-for="review in financial.reviews.filter(r=>!r.resolved)" :key="review.paymentId" class="btn btn-warning mt-3" :disabled="busy||needsReload||!note.trim()" @click="submit('REVIEW_REFUND',review.paymentId)">核對並模擬退款 {{ review.paymentId }}</button></template><button v-if="returned?.canReceive&&has('orders.return.receive.mock')" class="btn btn-primary mt-3" :disabled="busy||needsReload||!note.trim()||!disposition" @click="submit('RETURN_RECEIVE')">記錄模擬收貨驗收</button><button v-if="returned?.canReject&&has('orders.return.reject.mock')" class="btn btn-outline-danger mt-3" :disabled="busy||needsReload||!note.trim()" @click="submit('RETURN_REJECT')">拒絕演練退貨申請</button><button v-if="returned?.canRefund&&has('orders.return.refund.mock')" class="btn btn-danger mt-3" :disabled="busy||needsReload||!note.trim()" @click="submit('RETURN_REFUND')">執行模擬退貨退款</button></template></div>
<section v-if="returned" data-testid="staff-returns"><h3>整筆退貨演練</h3><p>先記錄收貨驗收，再按驗收結果退款；只有可重新入庫商品會在退款時回補一次庫存。</p><p v-if="!returned.mockEnabled">此環境未啟用模擬退貨。</p><template v-if="returned.request"><strong>{{ returnStatus(returned.request.status) }}</strong><p>顧客申請原因：{{ returned.request.reason }}</p><p v-if="returned.request.disposition">驗收結果：{{ dispositionName(returned.request.disposition) }}</p></template><p v-else>尚無退貨申請。</p><ol class="audit"><li v-for="event in returned.events" :key="event.requestId"><strong>{{ event.action==='RECEIVE'?'模擬收貨驗收':event.action==='REJECT'?'拒絕退貨申請':'模擬退貨退款' }} · {{ event.actorUsername }}</strong><p>{{ event.note }}</p><small>{{ dispositionName(event.disposition) }}</small><small>版本 {{ event.beforeVersion }} → {{ event.afterVersion }} · {{ orderTime(event.createdAt) }}</small><small>操作編號 {{ event.requestId }}</small></li></ol></section>
<section v-if="financial" data-testid="staff-refunds"><h3>退款與異常付款核對</h3><p>未出貨訂單可全額模擬退款並回補一次庫存；異常付款核對退款不動庫存。全程不會實際轉帳。</p><p v-if="!financial.mockEnabled">此環境未啟用模擬退款。</p><p v-if="selected.order.refund">已全額模擬退款 {{ money(selected.order.refund.amountTwd) }} · {{ orderTime(selected.order.refund.refundedAt) }}</p><ul><li v-for="review in financial.reviews" :key="review.paymentId">{{ review.paymentId }} · {{ money(review.amountTwd) }} · {{ review.resolved?'已核對並模擬退款':'待核對，暫停履約與訂單退款' }}<ul><li v-for="notification in review.notifications" :key="notification.eventId">{{ notification.outcome==='SUCCESS'?'成功通知':'失敗通知' }} · {{ notification.disposition }} · {{ orderTime(notification.receivedAt) }}<small>原通知編號 {{ notification.eventId }}</small></li></ul></li></ul><p v-if="!financial.events.length">尚無退款紀錄。</p><ol class="audit"><li v-for="event in financial.events" :key="event.requestId"><strong>{{ event.action==='ORDER_REFUND'?'訂單模擬退款／庫存回補':event.action==='RETURN_REFUND'?'退貨模擬退款（依驗收處置）':'異常付款核對模擬退款／庫存不變' }} · {{ money(event.amountTwd) }} · {{ event.actorUsername }}</strong><p>{{ event.note }}</p><small>版本 {{ event.beforeVersion }} → {{ event.afterVersion }} · {{ orderTime(event.createdAt) }}</small><small>操作編號 {{ event.requestId }}</small></li></ol></section>
<template v-if="has('orders.audit')"><h3>履約稽核紀錄</h3><p v-if="!events.length">尚無履約紀錄。</p><ol class="audit"><li v-for="event in events" :key="event.requestId"><strong>{{ event.action==='SHIP'?'模擬出貨':'模擬送達' }} · {{ event.actorUsername }}</strong><p>{{ event.note }}</p><small>版本 {{ event.beforeVersion }} → {{ event.afterVersion }} · {{ orderTime(event.createdAt) }}</small><small>操作編號 {{ event.requestId }}</small></li></ol></template></article></div></section></div></div></template>
<style scoped>.staff-orders{max-width:1400px;color:#292e29}.staff-orders h1{font-size:28px}.staff-orders h2{font-size:21px}.staff-orders h3{font-size:18px;margin-top:24px}.filters{display:flex;flex-wrap:wrap;align-items:end;gap:12px;margin:24px 0}.filter-field{min-width:160px}.workspace{display:grid;grid-template-columns:minmax(260px,1fr) minmax(0,2fr);gap:24px}.order-row{display:block;width:100%;text-align:left;background:white;border:0;border-bottom:1px solid #ddd;padding:16px 0;color:#292e29;overflow-wrap:anywhere}.order-row span,.order-row small,.audit small{display:block;margin-top:6px}.staff-orders article{overflow-wrap:anywhere}.staff-orders li{color:#292e29}.audit{padding-left:20px}.audit p{white-space:pre-wrap;margin-top:10px}.audit li{margin-top:20px}.staff-orders nav{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-top:20px}.staff-orders textarea{margin-top:8px}@media(max-width:950px){.workspace{grid-template-columns:1fr}}@media(max-width:500px){.filter-field{width:100%}}</style>
